const distance3D = function (a, b) { // 3D distance formula. But this is squared (d²)
    return Math.pow(a.x - b.x, 2) + Math.pow(a.y - b.y, 2) + Math.pow(a.z - b.z, 2);
}

const segmentTrees = {}; // each checkpoint segment gets their own KD tree
// Now you can use treeNearest(point, 1); and getProgress(nearest[0][0], nearest[0][1]);

// Using this to only call 'Math.pow' (ammo custom math) after simulation math has finished loading
addSharedEventListener("onAmmoLoaded", () => { // ready = before AI_Init or communicator ready, we start as soon as full_simulation_bundle.js has loaded its math
    for (let i = 0; i < Object.keys(pointSegments).length; i++) {
        const segmentCopy = [ ...pointSegments[i] ]; // easy fix, just make a copy of original points
        // Somehow this kdTree reverses the order of points array!
        const tree = new kdTree(segmentCopy, distance3D, ["x", "y", "z"]);
        //segmentPoints.reverse(); // So now bring the array back to the correct order

        segmentTrees[i] = tree.nearest; // add the .nearest function from the tree
    }

    const segmentIndex = 0;
    const treeNearest = segmentTrees[segmentIndex]; 
    //const point = { x: 5, y: 5, z: 5 };
    const point = {x: -105.50907897949219, y: 75.72852325439453, z: 34.90763473510742};
    const nearest = treeNearest(point, 1);
    console.log(nearest[0]);

    // Query the nearest *count* neighbours to a point, with an optional maximal search distance.
    // Result is an array with *count* elements.
    // Each element is an array with two components: the searched point and the distance to it.
    // tree.nearest(point, count, [maxDistance]);


    const progress = getProgress(nearest[0][0]);
    const segmentLength = pointSegments[segmentIndex].length;
    console.log("Progress:", (progress / flatPoints.length * 100).toFixed(2) + "%");
});


function getProgress(nearestPoint) {
    //const nearestIndex = flatPoints.indexOf(nearestPoint); // checks pointer, not properties!
    /*const nearestIndex = flatPoints.findIndex(point =>
        point.x === nearestPoint.x &&
        point.y === nearestPoint.y &&
        point.z === nearestPoint.z
    );*/
    const nearestIndex = nearestPoint.i; // global index, was precomputed. O(1) :D
    return nearestIndex;
}

function getDistanceSinceTrackBegin(nearestPointIndex) { // put in the index of point, not point xyz data
    let distanceSinceStart = 0;
    for (let i = 1; i <= nearestPointIndex; i++) { // pretty inefficient, don't use too much    // Actually, just use 'index * 0.5' to get a rough acceptable distance!
        const p1 = flatPoints[i - 1];
        const p2 = flatPoints[i];
        distanceSinceStart += Math.sqrt(distance3D(p1, p2));
    }
    return distanceSinceStart; // An approximate path distance, as the car can be any distance from the nearest point
    // Meaning this only gives back the distance that that POINT is from the start, not the car
}


